from timeit import default_timer
import time


def _convert_bytes(nbytes, unit="B"):
    if unit == "B":
        res = nbytes
    elif unit == "MB":
        res = float(nbytes / (1024 * 1024))
    else:
        raise ValueError("Invalid unit='%s'" % unit)
    return res


